function parseThresholdString(thresholdStr: string): [string, number] {
  const parts = thresholdStr.split('=');
  if (parts.length !== 2) {
    throw new Error(`Invalid threshold format: "${thresholdStr}". Expected format: <metric>=<number>`);
  }
  const [metric, valueStr] = parts;
  const value = Number.parseFloat(valueStr);
  if (Number.isNaN(value) || value < 0 || value > 1) {
    throw new Error(
      `Invalid threshold for "${metric}": "${valueStr}". Threshold must be a number between 0 and 1.`
    );
  }
  return [metric, value];
}

function parseThresholds(thresholdStrings: string[] = []): Record<string, number> {
  const thresholds: Record<string, number> = {};
  for (const str of thresholdStrings) {
    try {
      const [metric, value] = parseThresholdString(str);
      thresholds[metric] = value;
    } catch (error) {
      log.error('Threshold parsing error.', {
        error: error instanceof Error ? error.message : String(error)
      });
      process.exit(2);
    }
  }
  return thresholds;
}

function runEvalCommand(options: EvalOptions) {
  assertFileExists(options.outputs);

  const thresholds = parseThresholds(options.threshold);
  const thresholdStrings = options.threshold || [];

  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
    outputsPath: options.outputs,
    referencesPath: options.references
  });
  const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
    outputs: dataset.outputs,
    references: dataset.references
  });

  let validatedThresholds: Array<{ metric: string; min: number }> = [];
  if (thresholdStrings.length > 0) {
    const { validatedThresholds: valid, errors } = (Eval.validateThresholds as unknown as (config: unknown) => any)(
      thresholds,
      evaluations
    );
    if (errors.length > 0) {
      log.error('Threshold validation failed.', { errors });
      process.exit(2);
    }
    validatedThresholds = valid;
  }

  const report = (Eval.generateReport as unknown as (config: unknown) => any)({
    evaluations,
    outputsPath: dataset.outputsPath,
    referencesPath: dataset.referencesPath,
    thresholds: validatedThresholds.length > 0 ? validatedThresholds : undefined
  });
  const resolvedPath = (Eval.writeReport as unknown as (config: unknown) => string)({
    report,
    format: options.format ?? 'json',
    reportPath: options.report
  });
  log.success('Evaluation report generated.', { path: resolvedPath });

  if (validatedThresholds.length > 0 && report.passed === false) {
    process.exit(1);
  }
}

