73	      errors.push(`Invalid threshold for ${metricId}: ${minValue}. Threshold must be a number between 0 and 1.`);
74	      continue;
75	    }
76	    validatedThresholds.push({ metric: metricId, min: minValue });
77	  }
78	
79	  return { validatedThresholds, errors };
80	}
