82	export function evaluateThresholds(thresholds, metrics) {
83	  const thresholdResults = [];
84	  let allPassed = true;
85	
86	  thresholds.forEach(({ metric: metricId, min }) => {
87	    const metric = metrics.find((m) => m.id === metricId);
88	    const score = metric?.score;
