import fs from 'fs';
import os from 'os';
import path from 'path';
import { afterEach, describe, expect, it } from 'vitest';

import {
  generateReport,
  loadDataset,
  runEvaluations,
  writeReport,
  validateThresholds,
  evaluateThresholds
} from './index.js';

const tmpDirs = [];
afterEach(() => {
  while (tmpDirs.length) {
    fs.rmSync(tmpDirs.pop(), { recursive: true, force: true });
  }
});

const createTempDir = () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'frai-eval-'));
  tmpDirs.push(dir);
  return dir;
};

describe('Evaluation harness', () => {
  it('loads outputs and references', () => {
    const dir = createTempDir();
    const outputsPath = path.join(dir, 'outputs.json');
    const referencesPath = path.join(dir, 'references.json');
    fs.writeFileSync(outputsPath, JSON.stringify(['Hello', 'World'], null, 2));
    fs.writeFileSync(referencesPath, JSON.stringify(['hello', 'world'], null, 2));

    const dataset = loadDataset({ outputsPath, referencesPath });
    expect(dataset.outputs).toEqual(['Hello', 'World']);
    expect(dataset.references).toEqual(['hello', 'world']);
  });

  it('runs default evaluations', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'friendly world'],
      references: ['hello', 'friendly world']
    });
    const exact = evaluations.find((metric) => metric.id === 'exact_match');
    const toxicity = evaluations.find((metric) => metric.id === 'toxicity');

    expect(exact.score).toBeCloseTo(1, 4);
    expect(toxicity.score).toBe(1);
  });

  it('generates and writes report', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      generatedAt: '2024-01-01T00:00:00.000Z'
    });
    expect(report.metadata.totalSamples).toBe(1);

    const dir = createTempDir();
    const jsonPath = writeReport({
      report,
      format: 'json',
      reportPath: path.join(dir, 'report.json')
    });
    const markdownPath = writeReport({
      report,
      format: 'markdown',
      reportPath: path.join(dir, 'report.md')
    });

    expect(fs.existsSync(jsonPath)).toBe(true);
    expect(fs.existsSync(markdownPath)).toBe(true);
  });

  it('validates thresholds', () => {
    const metrics = [
      { id: 'exact_match', score: 0.9 },
      { id: 'toxicity', score: 0.95 }
    ];

    const { validatedThresholds, errors } = validateThresholds(
      { exact_match: 0.8, toxicity: 0.9 },
      metrics
    );
    expect(validatedThresholds).toHaveLength(2);
    expect(errors).toHaveLength(0);
  });

  it('rejects invalid threshold values', () => {
    const metrics = [
      { id: 'exact_match', score: 0.9 }
    ];

    const { validatedThresholds, errors } = validateThresholds(
      { exact_match: 1.5 },
      metrics
    );
    expect(validatedThresholds).toHaveLength(0);
    expect(errors).toHaveLength(1);
    expect(errors[0]).toContain('must be a number between 0 and 1');
  });

  it('rejects unknown metric ids', () => {
    const metrics = [
      { id: 'exact_match', score: 0.9 }
    ];

    const { validatedThresholds, errors } = validateThresholds(
      { unknown_metric: 0.8 },
      metrics
    );
    expect(validatedThresholds).toHaveLength(0);
    expect(errors).toHaveLength(1);
    expect(errors[0]).toContain('Unknown metric id');
  });

  it('evaluates thresholds correctly', () => {
    const metrics = [
      { id: 'exact_match', score: 0.9 },
      { id: 'toxicity', score: 0.85 }
    ];
    const thresholds = [
      { metric: 'exact_match', min: 0.8 },
      { metric: 'toxicity', min: 0.9 }
    ];

    const { thresholdResults, allPassed } = evaluateThresholds(thresholds, metrics);
    expect(thresholdResults).toHaveLength(2);
    expect(thresholdResults[0].passed).toBe(true);
    expect(thresholdResults[1].passed).toBe(false);
    expect(allPassed).toBe(false);
  });

  it('handles null scores in thresholds', () => {
    const metrics = [
      { id: 'exact_match', score: null }
    ];
    const thresholds = [
      { metric: 'exact_match', min: 0.8 }
    ];

    const { thresholdResults, allPassed } = evaluateThresholds(thresholds, metrics);
    expect(thresholdResults[0].score).toBe(null);
    expect(thresholdResults[0].passed).toBe(false);
    expect(allPassed).toBe(false);
  });

  it('includes thresholds in report', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'World'],
      references: ['hello', 'world']
    });
    const thresholds = [
      { metric: 'exact_match', min: 0.5 }
    ];
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds,
      generatedAt: '2024-01-01T00:00:00.000Z'
    });

    expect(report.passed).toBe(true);
    expect(report.thresholds).toHaveLength(1);
    expect(report.thresholds[0].metric).toBe('exact_match');
    expect(report.thresholds[0].passed).toBe(true);
  });
});

