388	      if (!proceed) {
389	        log.info('Documentation generation cancelled.');
390	        return;
391	      }
392	    }
393	  }
394	
395	  const answers = await Questionnaire.runQuestionnaire({ prompt: (questions) => inquirer.prompt(questions) });
396	  log.info('Generating documentation artefacts...');
397	  const aiTips = await generateAITips(answers, apiKey ?? null, scanResult);
398	  const tipSections = extractTips(aiTips);
399	
400	  const { checklist, modelCard, riskFile } = Documents.generateDocuments({
401	    answers,
402	    tips: tipSections
403	  });
404	
405	  fs.writeFileSync('checklist.md', checklist, 'utf8');
406	  fs.writeFileSync('model_card.md', modelCard, 'utf8');
407	  fs.writeFileSync('risk_file.md', riskFile, 'utf8');
408	
409	  log.success('Responsible AI documentation generated.', {
410	    files: DOC_FILENAMES
411	  });
412	
413	  if (options.exportPdf) {
414	    exportDocsAsPdf();
415	  }
416	
417	  if (!apiKey) {
418	    log.warn('AI guidance tips were skipped because no API key is configured.');
419	  }
420	}
