477	function parseThresholdString(thresholdStr: string): [string, number] {
478	  const parts = thresholdStr.split('=');
479	  if (parts.length !== 2) {
480	    throw new Error(`Invalid threshold format: "${thresholdStr}". Expected format: <metric>=<number>`);
481	  }
482	  const [metric, valueStr] = parts;
483	  const value = Number.parseFloat(valueStr);
484	  if (Number.isNaN(value) || value < 0 || value > 1) {
485	    throw new Error(
486	      `Invalid threshold for "${metric}": "${valueStr}". Threshold must be a number between 0 and 1.`
487	    );
488	  }
489	  return [metric, value];
490	}
491	
492	function parseThresholds(thresholdStrings: string[] = []): Record<string, number> {
493	  const thresholds: Record<string, number> = {};
494	  for (const str of thresholdStrings) {
495	    try {
496	      const [metric, value] = parseThresholdString(str);
497	      thresholds[metric] = value;
498	    } catch (error) {
499	      log.error('Threshold parsing error.', {
500	        error: error instanceof Error ? error.message : String(error)
501	      });
502	      process.exit(2);
503	    }
504	  }
505	  return thresholds;
506	}
