508	function runEvalCommand(options: EvalOptions) {
509	  assertFileExists(options.outputs);
510	
511	  const thresholds = parseThresholds(options.threshold);
512	  const thresholdStrings = options.threshold || [];
513	
514	  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
515	    outputsPath: options.outputs,
516	    referencesPath: options.references
517	  });
518	  const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
519	    outputs: dataset.outputs,
520	    references: dataset.references
521	  });
522	
523	  let validatedThresholds: Array<{ metric: string; min: number }> = [];
524	  if (thresholdStrings.length > 0) {
525	    const validateThresholds = Eval.validateThresholds as unknown as (thresholds: unknown, metrics: unknown) => { validatedThresholds: Array<{ metric: string; min: number }>; errors: string[] };
526	    const { validatedThresholds: valid, errors } = validateThresholds(thresholds, evaluations);
527	    if (errors.length > 0) {
528	      log.error('Threshold validation failed.', { errors });
529	      process.exit(2);
530	    }
531	    validatedThresholds = valid;
532	  }
533	
534	  const report = (Eval.generateReport as unknown as (config: unknown) => any)({
535	    evaluations,
536	    outputsPath: dataset.outputsPath,
537	    referencesPath: dataset.referencesPath,
538	    thresholds: validatedThresholds.length > 0 ? validatedThresholds : undefined
539	  });
540	  const resolvedPath = (Eval.writeReport as unknown as (config: unknown) => string)({
541	    report,
542	    format: options.format ?? 'json',
543	    reportPath: options.report
544	  });
545	  log.success('Evaluation report generated.', { path: resolvedPath });
546	
547	  if (validatedThresholds.length > 0 && report.passed === false) {
548	    process.exit(1);
549	  }
550	}
